$mdPage = max(1, (int)($_GET['p'] ?? 1));
$mdPerPage = (int)($_GET['per_page'] ?? 25);
$mdData = match ($tab) {
    'produtos' => $directory->products($mdFilters, $mdPage, $mdPerPage),
    'cfops' => $directory->cfops($mdFilters, $mdPage, $mdPerPage),
